PRAGMA foreign_keys = ON;
CREATE TABLE events(id TEXT PRIMARY KEY, settings TEXT NOT NULL CHECK(json_valid(settings)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE households(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,name TEXT NOT NULL,greeting TEXT NOT NULL,plus_ones INTEGER NOT NULL DEFAULT 0 CHECK(plus_ones BETWEEN 0 AND 5),revision INTEGER NOT NULL DEFAULT 0,pomegranates INTEGER NOT NULL DEFAULT 0 CHECK(pomegranates>=0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX households_event ON households(event_id);
CREATE TABLE guests(id TEXT PRIMARY KEY,household_id TEXT NOT NULL REFERENCES households(id) ON DELETE CASCADE,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('adult','child')),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','attending','declined','maybe')),is_plus_one INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX guests_household ON guests(household_id);
CREATE TABLE invitation_tokens(id TEXT PRIMARY KEY,household_id TEXT NOT NULL REFERENCES households(id) ON DELETE CASCADE,hash TEXT NOT NULL UNIQUE,revoked_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX tokens_household ON invitation_tokens(household_id);
CREATE TABLE rsvp_responses(id TEXT PRIMARY KEY,household_id TEXT NOT NULL UNIQUE REFERENCES households(id) ON DELETE CASCADE,dietary TEXT NOT NULL,allergies TEXT NOT NULL,message TEXT NOT NULL,contact TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE gift_campaigns(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,kind TEXT NOT NULL CHECK(kind IN ('console','mystery')),config TEXT NOT NULL CHECK(json_valid(config)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX campaign_event ON gift_campaigns(event_id);
CREATE TABLE gift_pledges(id TEXT PRIMARY KEY,household_id TEXT NOT NULL REFERENCES households(id) ON DELETE CASCADE,campaign_id TEXT NOT NULL REFERENCES gift_campaigns(id) ON DELETE CASCADE,amount_cents INTEGER NOT NULL CHECK(amount_cents>=0),received_cents INTEGER NOT NULL DEFAULT 0 CHECK(received_cents BETWEEN 0 AND amount_cents),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(household_id,campaign_id));
CREATE INDEX pledges_campaign ON gift_pledges(campaign_id);
CREATE TABLE registry_items(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,name TEXT NOT NULL,unit TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>=0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX registry_event ON registry_items(event_id);
CREATE TABLE registry_commitments(id TEXT PRIMARY KEY,household_id TEXT NOT NULL REFERENCES households(id) ON DELETE CASCADE,item_id TEXT NOT NULL REFERENCES registry_items(id) ON DELETE CASCADE,quantity INTEGER NOT NULL CHECK(quantity>=0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(household_id,item_id));
CREATE INDEX commitments_item ON registry_commitments(item_id);
CREATE TRIGGER registry_insert_capacity BEFORE INSERT ON registry_commitments BEGIN SELECT CASE WHEN NEW.quantity+COALESCE((SELECT SUM(quantity) FROM registry_commitments WHERE item_id=NEW.item_id AND household_id!=NEW.household_id),0)>(SELECT quantity FROM registry_items WHERE id=NEW.item_id) THEN RAISE(ABORT,'registry_capacity') END; END;
CREATE TRIGGER registry_update_capacity BEFORE UPDATE ON registry_commitments BEGIN SELECT CASE WHEN NEW.quantity+COALESCE((SELECT SUM(quantity) FROM registry_commitments WHERE item_id=NEW.item_id AND id!=OLD.id),0)>(SELECT quantity FROM registry_items WHERE id=NEW.item_id) THEN RAISE(ABORT,'registry_capacity') END; END;
CREATE TRIGGER registry_reduce_capacity BEFORE UPDATE OF quantity ON registry_items BEGIN SELECT CASE WHEN NEW.quantity<COALESCE((SELECT SUM(quantity) FROM registry_commitments WHERE item_id=NEW.id),0) THEN RAISE(ABORT,'registry_capacity') END; END;
CREATE TABLE guestbook_entries(id TEXT PRIMARY KEY,household_id TEXT NOT NULL REFERENCES households(id) ON DELETE CASCADE,message TEXT NOT NULL,approved INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX guestbook_household ON guestbook_entries(household_id);
CREATE TABLE admin_users(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,salt TEXT NOT NULL,password_hash TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE sessions(hash TEXT PRIMARY KEY,admin_id TEXT REFERENCES admin_users(id) ON DELETE CASCADE,invitation_id TEXT REFERENCES invitation_tokens(id) ON DELETE CASCADE,expires_at TEXT NOT NULL,CHECK((admin_id IS NULL)!=(invitation_id IS NULL)));
CREATE INDEX session_expiry ON sessions(expires_at);
CREATE TABLE audit_logs(id TEXT PRIMARY KEY,actor_id TEXT NOT NULL,action TEXT NOT NULL,resource_id TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX audit_created ON audit_logs(created_at);
CREATE TABLE rate_limits(bucket TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE submissions(id TEXT PRIMARY KEY,household_id TEXT NOT NULL REFERENCES households(id) ON DELETE CASCADE,body_hash TEXT NOT NULL,created_at TEXT NOT NULL);
